void typeChar(char c) {
  Keyboard.press(c);
  delay(KEY_HOLD);            // tangenten hålls nere en kort stund
  Keyboard.release(c);
  delay(random(GAP_MIN, GAP_MAX + 1));
  if (c == '\n') delay(NEWLINE_PAUSE);  // låt editorn hinna med efter Enter
}

void setup() {
  randomSeed(analogRead(0));
  Keyboard.begin();
  delay(START_DELAY);

  const size_t len = strlen_P(text);  // räknas en gång, inte i varje varv
  for (size_t i = 0; i < len; i++) {
    typeChar(pgm_read_byte(&text[i]));
  }

  Keyboard.end();
}

